import {enrich,summary,themeRates,compare,terms,yearly,THEMES} from './text-analysis.js';
import {csvEscape} from './analysis.js';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n===null?'—':n.toLocaleString('en-US',{maximumFractionDigits:1}),share=x=>x===null?'—':num(x*100)+'%',money=x=>x===null?'—':'$'+Math.round(x).toLocaleString('en-US');
let corpus=[],synthetic=false,comparison=[],publicCorpus=false;
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function table(headers,rows,caption=''){return `<table>${caption?`<caption>${esc(caption)}</caption>`:''}<thead><tr>${headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`;}
function selected(){return corpus.filter(j=>($('q-source').value==='all'||j.source===$('q-source').value)&&($('q-family').value==='all'||j.family===$('q-family').value));}
function resetYears(){const years=[...new Set(selected().map(j=>j.year))].sort();for(const id of ['q-base','q-current']){const previous=$(id).value;$(id).innerHTML=years.map(y=>`<option>${esc(y)}</option>`).join('');$(id).value=years.includes(previous)?previous:(id==='q-base'?years[0]:years.at(-1))||'';}}
export function clearCorpus(){corpus=[];comparison=[];$('quant-body').hidden=true;$('quant-empty').hidden=false;$('quant-status').textContent='NO POSTING CORPUS LOADED';}
export function setCorpus(rows,demo=false,metadata=null){
 corpus=enrich(rows,{allowPrepared:!!metadata});synthetic=demo;publicCorpus=!!metadata;
 $('q-source').innerHTML='<option value="all">All sources (exploratory)</option>'+[...new Set(rows.map(j=>j.source))].sort().map(source=>`<option>${esc(source)}</option>`).join('');$('q-source').value=metadata?.default_source||'all';
 const years=[...new Set(corpus.map(j=>j.year))].sort();for(const id of ['q-base','q-current'])$(id).innerHTML=years.map(y=>`<option>${esc(y)}</option>`).join('');
 $('q-base').value=years[0];$('q-current').value=years.at(-1);$('q-family').value='all';$('q-search').value='';
 $('quant-status').textContent=metadata?'PUBLIC CORPUS · SNAPSHOT SAMPLE':demo?'SYNTHETIC EXAMPLE · NOT MARKET EVIDENCE':'IMPORTED CORPUS · COVERAGE UNVERIFIED';
 $('corpus-banner').className='corpus-banner'+(demo?' synthetic':'');
 $('corpus-banner').textContent=demo?'SYNTHETIC EXAMPLE: all postings, companies, descriptions and salaries in this corpus are invented to demonstrate calculations. Do not interpret these results as hiring trends.':`${rows.length} accepted postings loaded. Analyses describe this corpus only. Check consistent source coverage, missing text, reposts, and partial years before interpreting a trend. Uploads stay in memory and disappear on refresh.`;
 if(metadata){$('corpus-banner').textContent=metadata.banner||`PUBLIC CORPUS: ${rows.length} reviewed, deduplicated US research postings from Arsh Koneru’s LinkedIn dataset, versions 9 and 13. CC BY-SA 4.0. ${metadata.limitations} View source coverage and audit below.`;}
 $('quant-body').hidden=false;$('quant-empty').hidden=true;resetYears();render();
}
function render(){
 const jobs=selected(),s=summary(jobs),base=$('q-base').value,current=$('q-current').value,a=jobs.filter(j=>j.year===base),b=jobs.filter(j=>j.year===current),bs=summary(a),cs=summary(b);
 $('quant-stats').innerHTML=[['Observed postings',num(s.n),`${new Set(jobs.map(j=>j.company)).size} employers · ${new Set(jobs.map(j=>j.source)).size} sources`],['Description coverage',s.n?share(s.textN/s.n):'—',`${s.textN}/${s.n} have text · ${s.n-s.textN} missing`],['Median extracted experience',s.experienceMedian===null?'—':num(s.experienceMedian)+' years',`${s.experienceN}/${s.n} explicit unambiguous values`],['Median salary midpoint',money(s.salaryMedian),`${s.salaryN}/${s.n} valid USD annual ranges · IQR ${money(s.salaryQ1)}–${money(s.salaryQ3)}`]].map(([l,v,n])=>`<div class="stat"><span>${esc(l)}</span><strong>${esc(v)}</strong><small>${esc(n)}</small></div>`).join('');
 comparison=compare(a,b);const biggest=comparison.find(t=>t.delta!==null&&Math.abs(t.delta)>0);
 let insight=!bs.textN||!cs.textN?'Both year cohorts need descriptions before a text comparison can be calculated.':base===current?`Single-year cohort (${base||'no year'}): ${cs.textN} descriptions. ${themeRates(b)[0].count} mention ${themeRates(b)[0].name.toLowerCase()}. Choose different years when available for a comparison.`:biggest?`The largest absolute dictionary-theme difference is “${biggest.name}”: ${share(biggest.baseShare)} (${biggest.baseCount}/${biggest.baseN}) in ${base} versus ${share(biggest.share)} (${biggest.count}/${biggest.n}) in ${current}, a ${num(Math.abs(biggest.delta))} percentage-point ${biggest.delta>0?'increase':'decrease'}.`:'All dictionary themes have identical mention shares across these two cohorts.';
 $('quant-insight').innerHTML=`<span class="insight-icon">∑</span><div><div class="eyebrow">${synthetic?'SYNTHETIC EXAMPLE RESULT':'DESCRIPTIVE CORPUS COMPARISON'}</div><p>${esc(insight)}</p><small>Selected from 17 themes by absolute difference; exploratory, not a statistical significance test. No causal or national market inference.</small></div>`;
 $('comparison').innerHTML=table(['Theme / category',`${base} mentions / text N`,`${base} share`,`${current} mentions / text N`,`${current} share`,'Δ percentage points'],comparison.map(t=>`<tr><td><strong>${esc(t.name)}</strong><br><small>${esc(t.category)}</small></td><td>${t.baseCount} / ${t.baseN}</td><td>${share(t.baseShare)}</td><td>${t.count} / ${t.n}</td><td><span class="share-bar" style="width:${(t.share||0)*65}px"></span>${share(t.share)}</td><td class="delta">${t.delta===null?'—':(t.delta>0?'+':'')+num(t.delta)}</td></tr>`));
 const warnings=[];if($('q-source').value==='all'&&new Set(jobs.map(j=>j.source)).size>1)warnings.push('MIXED SOURCES: source and remote-work coverage differ. Differences are not evidence of historical market change.');if($('q-source').value==='Jobicy (remote)')warnings.push('Remote-only sample; archive through November 12, 2026. Two distinct US roles; no population inference.');if(bs.textN<30||cs.textN<30)warnings.push('Small text cohort (under 30 descriptions): differences are unstable.');if(base===current)warnings.push('Same year selected: both columns describe the same cohort.');warnings.push(`${base}: ${bs.n-bs.textN}/${bs.n} missing descriptions; ${current}: ${cs.n-cs.textN}/${cs.n} missing descriptions. Matching source names does not establish comparable coverage.`);$('comparison-note').textContent=warnings.join(' ');
 $('quant-annual').innerHTML=table(['Year','Postings','Text N / total','Sources','Experience median (N)','Pay median (N)'],yearly(jobs).map(r=>`<tr><td>${r.year}</td><td>${r.n}</td><td>${r.textN} / ${r.n}</td><td>${new Set(jobs.filter(j=>j.year===r.year).map(j=>j.source)).size}</td><td>${num(r.experienceMedian)} (${r.experienceN})</td><td>${money(r.salaryMedian)} (${r.salaryN})</td></tr>`),'Observed sample by year; years may be incomplete.');
 $('terms-note').textContent=`${current} cohort · ${cs.textN} descriptions · minimum ${$('q-min').value} documents per term.`;
 const termRows=terms(b,Number($('q-min').value));$('terms').innerHTML=termRows.length?termRows.map(t=>`<span class="term-chip">${esc(t.term)}<small>${t.count}/${t.n} · ${share(t.share)}</small></span>`).join(''):'<p>No terms meet this document threshold.</p>';
 evidence();
}
function evidence(){const jobs=selected(),theme=$('q-theme').value,t=THEMES.find(x=>x.name===theme);const years=[...new Set(jobs.map(j=>j.year))].sort();$('trajectory').innerHTML=table(['Year','Theme mentions','Descriptions','Share'],years.map(year=>{const rows=themeRates(jobs.filter(j=>j.year===year)),r=rows.find(x=>x.name===theme);return `<tr><td>${year}</td><td>${r.count}</td><td>${r.n}</td><td>${share(r.share)}</td></tr>`;}),`${theme}: annual mention share`);
 const search=$('q-search').value.trim().toLowerCase();const matches=jobs.filter(j=>j.mentions.includes(theme)&&(!search||(j.text+' '+(j.docTerms||[]).join(' ')+' '+j.company).toLowerCase().includes(search)));$('evidence-count').textContent=`${matches.length} matching postings · showing first ${Math.min(20,matches.length)}`;
 $('evidence').innerHTML=matches.slice(0,20).map(j=>{if(j.analysis){const link=/^https:\/\/jobicy\.com\/jobs\//.test(j.job_posting_url||'')?`<a href="${esc(j.job_posting_url)}" target="_blank" rel="noreferrer">View full listing on Jobicy ↗</a>`:'';return `<article class="evidence-row"><h4>${esc(j.title)} · ${esc(j.company)}</h4><div class="evidence-meta">${esc(j.posted_date)} · ${esc(j.source)} · ID: ${esc(j.id)} · Last archive publication: ${esc(j.last_archive_publication)}</div><p>Matched phrase: <strong>${esc(j.analysis.matches[theme]||theme)}</strong>. Full description analyzed during data preparation.</p><p>Extracted experience: ${j.experience.value===null?'unknown':num(j.experience.value)+' years'} · Salary midpoint: ${money(j.salary)}</p>${link}</article>`;}const match=t.pattern.exec(j.text),start=Math.max(0,match.index-120),end=Math.min(j.text.length,match.index+match[0].length+200),snippet=(start?'…':'')+j.text.slice(start,end)+(end<j.text.length?'…':'');return `<article class="evidence-row"><h4>${esc(j.title)} · ${esc(j.company)}</h4><div class="evidence-meta">${esc(j.posted_date)} · Source: ${esc(j.source)} · ID: <code>${esc(j.id)}</code></div><p>${esc(snippet)}</p><details><summary>Full cleaned description & extracted fields</summary><p>${esc(j.text)}</p><p>Experience: ${esc(j.experience.evidence||'No explicit match')} · Salary midpoint: ${money(j.salary)}</p></details></article>`;}).join('')||'<p>No matching descriptions in this selection.</p>';
}
$('q-theme').innerHTML=THEMES.map(t=>`<option>${esc(t.name)}</option>`).join('');for(const id of ['q-family','q-base','q-current','q-min'])$(id).onchange=render;$('q-source').onchange=()=>{resetYears();render();};$('q-family').onchange=()=>{resetYears();render();};$('q-theme').onchange=evidence;$('q-search').oninput=evidence;$('q-clear').onclick=clearCorpus;
$('q-export').onclick=()=>{const header=['corpus_type','source_filter','family','baseline_year','comparison_year','theme','category','baseline_matches','baseline_text_n','baseline_share','comparison_matches','comparison_text_n','comparison_share','delta_pp'];download((synthetic?'SYNTHETIC-':'')+'theme-comparison.csv',[header.join(','),...comparison.map(t=>[synthetic?'synthetic':publicCorpus?'public':'imported',$('q-source').value,$('q-family').value,$('q-base').value,$('q-current').value,t.name,t.category,t.baseCount,t.baseN,t.baseShare??'',t.count,t.n,t.share??'',t.delta??''].map(csvEscape).join(','))].join('\n'));};
$('template-quant').onclick=()=>download('posting-text-schema.csv','id,title,company,posted_date,country,source,location,description,salary_min,salary_max,currency,salary_period\n');
$('demo').onclick=()=>{const rows=[];for(const year of ['2021','2022','2023','2024'])for(let i=0;i<12;i++){const later=Number(year)>=2023;const description=`SYNTHETIC EXAMPLE ONLY. Fictional UX research posting. Conduct user interviews and ${i%3?'usability testing':'ethnography'}. ${i%2?'Partner with stakeholders on research strategy.':'Run surveys with Qualtrics.'} ${later&&i%3?'Use SQL and Python for quantitative research. Evaluate AI and machine learning products.':'Conduct mixed-methods research.'} ${i%4?'Use Figma and Dovetail.':'Plan accessibility studies.'} ${later?'5+':'3–5'} years of research experience required.`;rows.push({id:`fiction-${year}-${i}`,title:i%4?'UX Researcher':'Senior User Researcher',family:'UX Research',company:`Fictional Company ${i%4+1}`,source:'SYNTHETIC_DEMO',country:'US',posted_date:`${year}-${String(i+1).padStart(2,'0')}-15`,year,month:`${year}-${String(i+1).padStart(2,'0')}`,description:i===11?'':description,salary_min:i%3?'':String(later?130000:100000),salary_max:i%3?'':String(later?170000:140000),currency:'USD',salary_period:'annual'});}setCorpus(rows,true);};
